eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   featuredProjects: () => (/* binding */ featuredProjects),\n/* harmony export */   getProject: () => (/* binding */ getProject),\n/* harmony export */   projects: () => (/* binding */ projects),\n/* harmony export */   statusLabel: () => (/* binding */ statusLabel)\n/* harmony export */ });\n/**\n * Projektdaten.\n *\n * Warum als typisierte Daten und nicht als JSX pro Seite: Jede Case-Study\n * braucht dieselben Bestandteile (Problem, Umsetzung, Entscheidungen, Grenze).\n * Als Daten lässt sich per Test prüfen, dass keines davon fehlt — als JSX\n * fällt eine vergessene Sektion erst beim Hinsehen auf, und meist nicht.\n *\n * Die Felder folgen dem Kontextdokument, insbesondere `limitation`: Zu jedem\n * Projekt gehört eine ehrliche Grenze. Das Feld ist deshalb Pflicht, nicht\n * optional — man kann es nicht vergessen, ohne dass TypeScript meckert.\n */ const projects = [\n    {\n        slug: 'ml-market-runtime',\n        name: 'ML Market Runtime',\n        title: 'ML Market Runtime: Zeitreihen, Modellvalidierung und kontrollierte Ausführung',\n        summary: 'Research-Plattform für acht Forex-Zeitreihen mit Mehrquellen-Features, instrumentenspezifischen XGBoost-Modellen, Walk-forward-Validierung und getrennter Risikoebene.',\n        description: 'Die technische Case-Study betrachtet historische Kurs-, Makro- und Nachrichtendaten, Merkmalsberechnung, Training, Backtesting, Modellbereitstellung und Monitoring als zusammenhängendes ML-System. Sie enthält keine Renditeversprechen und keine Handelsempfehlung.',\n        role: 'ML-Pipeline, Backend, Desktop-Anwendung, Web-Dashboard, Risikologik und Systemintegration, eigenständig',\n        year: '2024 bis 2025',\n        status: 'lokal',\n        discipline: 'ai-systems',\n        stack: [\n            'Python',\n            'XGBoost',\n            'scikit-learn',\n            'pandas',\n            'NumPy',\n            'FastAPI',\n            'Electron',\n            'React',\n            'MongoDB',\n            'MetaTrader 5',\n            'yFinance',\n            'FRED API',\n            'News API'\n        ],\n        headlineDecision: 'Modellprognose und Ausführung sind getrennt: Ein Signal muss zusätzlich deterministische Risiko- und Verlustgrenzen passieren.',\n        problem: 'Modelle auf Finanzzeitreihen überfitten leicht, wenn zukünftige Informationen unbemerkt ins Training gelangen oder eine zufällige Aufteilung zeitliche Abhängigkeiten ignoriert. Selbst ein brauchbares Modell darf außerdem niemals direkt und unbegrenzt Aktionen auslösen.',\n        approach: 'Eine Python-Pipeline verbindet historische OHLCV-Daten von acht Währungspaaren mit Makro- und Nachrichtenmerkmalen. Sie berechnet Momentum-, Trend-, Volatilitäts-, Korrelations-, Session- und retracementbasierte Features und trainiert getrennte XGBoost-Klassifikatoren. Rollierende Trainings- und Testfenster bilden die zeitliche Reihenfolge ab. FastAPI, Electron und React stellen Steuerung, Verlauf und Risikometriken bereit.',\n        decisions: [\n            {\n                title: 'Walk-forward-Validierung statt zufälligem Train-Test-Split.',\n                rationale: 'Zeitreihen haben eine Richtung. Rollierende Fenster verhindern, dass zukünftige Marktphasen unbemerkt zum Training früherer Vorhersagen verwendet werden.'\n            },\n            {\n                title: 'Instrumentenspezifische Modelle und versionierte Feature-Konfiguration.',\n                rationale: 'Die acht Währungspaare besitzen unterschiedliche Dynamiken. Modell, Feature-Reihenfolge, Datenquellen und Trainingsparameter werden deshalb gemeinsam versioniert und beim Laden geprüft.'\n            },\n            {\n                title: 'Deterministische Risikoebene nach der Modellprognose.',\n                rationale: 'Confidence allein ist keine Risikosteuerung. Positionsgröße, Verlustgrenzen, Drawdown-Limit und zeitliche Regeln können ein Modellresultat jederzeit verwerfen.'\n            },\n            {\n                title: 'Monitoring über Desktop-Client und Web-Dashboard.',\n                rationale: 'Modellzustand, offene Prozesse, Historie und Risikometriken müssen unabhängig von der Trainingsumgebung beobachtbar und nachvollziehbar sein.'\n            }\n        ],\n        limitation: 'Research- und Engineering-Projekt. Backtests belegen keine zukünftige Profitabilität; es werden weder Anlageberatung noch öffentliche Live-Performance oder reale Erträge behauptet.',\n        sections: [\n            {\n                heading: 'Technischer Fokus',\n                body: 'Feature Engineering aus OHLCV-, Makro-, Nachrichten- und Cross-Pair-Daten, technische Indikatoren, retracementbasierte Merkmale, XGBoost, Walk-forward-Validierung, Backtesting ohne Look-ahead Bias, Modellversionierung und deterministische Risiko-Gates.'\n            }\n        ],\n        featured: false\n    },\n    {\n        slug: 'realtime-vision-runtime',\n        name: 'Realtime Vision Runtime',\n        title: 'Realtime Vision Runtime: hardwarebeschleunigte Computer-Vision-Pipeline',\n        summary: 'Private Computer-Vision-Plattform für latenzarme Objekterkennung mit austauschbaren Inferenz-Runtimes und einem getrennten Arduino-basierten Hardware-Layer.',\n        description: 'Die Case-Study konzentriert sich ausschließlich auf die technische Umsetzung: Capture, Preprocessing, neuronale Inferenz, Postprocessing, Runtime-Auswahl und Hardware-Kommunikation. Produktname, Einsatzzweck, Modelle und betrieblicher Kontext bleiben bewusst privat.',\n        role: 'Architektur, Computer Vision, Inferenz-Pipeline, Desktop-Client, Runtime-Abstraktion, serielles Protokoll und Arduino-Firmware, eigenständig',\n        year: '2023 bis 2026',\n        status: 'lokal',\n        discipline: 'ai-systems',\n        stack: [\n            'Python',\n            'C++',\n            'PyQt6',\n            'OpenCV',\n            'YOLO',\n            'ONNX Runtime',\n            'TensorRT',\n            'OpenVINO',\n            'CUDA',\n            'Arduino'\n        ],\n        headlineDecision: 'Die Inferenz ist von der Anwendung entkoppelt: TensorRT, ONNX Runtime und OpenVINO laufen hinter derselben Pipeline-Schnittstelle.',\n        problem: 'Eine Echtzeit-Vision-Pipeline muss auf sehr unterschiedlicher Hardware niedrige und stabile Latenzen liefern. Capture, Preprocessing, Inferenz und Postprocessing dürfen sich dabei nicht gegenseitig blockieren, und ein fehlendes GPU-Backend darf die Anwendung nicht unbrauchbar machen.',\n        approach: 'Ein standardisierter Frame-Flow verbindet Capture, normalisiertes Preprocessing, YOLO-Inferenz, Confidence-Filter und Non-Maximum Suppression. TensorRT, ONNX Runtime oder OpenVINO führen das Modell auf dem Hostsystem aus und werden passend zur vorhandenen Hardware gewählt. Erst die strukturierten Ergebnisse gehen über ein versioniertes serielles Protokoll an eine eigenständige Arduino-Firmware, die Timing, Gerätekommunikation und Hardware-Ausgabe übernimmt.',\n        decisions: [\n            {\n                title: 'Mehrere Inferenz-Runtimes hinter einem Adapter.',\n                rationale: 'TensorRT nutzt NVIDIA-Hardware maximal aus, ONNX Runtime deckt CUDA, DirectML und CPU ab, OpenVINO Intel-Systeme. Die fachliche Pipeline bleibt dabei unverändert und damit testbar.'\n            },\n            {\n                title: 'Deterministischer Hardware-Fallback statt harter GPU-Abhängigkeit.',\n                rationale: 'Beim Start werden verfügbare Provider geprüft und nach Eignung gewählt. Fehlt der schnellste Pfad, läuft dieselbe Pipeline kontrolliert auf einem kompatiblen Backend weiter.'\n            },\n            {\n                title: 'Pre- und Postprocessing als eigene Pipeline-Stufen.',\n                rationale: 'Resize, Normalisierung, Tensor-Layout, Confidence-Filter und NMS sind unabhängig vom Modellaufruf. Das erleichtert Profiling, Austausch und reproduzierbare Tests.'\n            },\n            {\n                title: 'Host-Inferenz und Arduino-Firmware bleiben getrennte Systeme.',\n                rationale: 'In dieser Architektur laufen die Modelle im Host-Runtime-Layer. Die Desktop-Anwendung sendet nur strukturierte Ergebnisse an den Arduino; Protokoll, Firmware, Geräteverhalten und Transport lassen sich dadurch unabhängig entwickeln und diagnostizieren.'\n            }\n        ],\n        limitation: 'Privates proprietäres Projekt. Produktname, konkreter Einsatzzweck, Datensätze, Modellgewichte, Konfigurationen und ausführbare Artefakte werden absichtlich nicht veröffentlicht.',\n        sections: [\n            {\n                heading: 'Technischer Fokus',\n                body: 'Der belegbare Schwerpunkt liegt auf Echtzeit-Computer-Vision, YOLO-Inferenz, ONNX-Modellformaten, TensorRT-Optimierung, OpenVINO, OpenCV, Provider-Fallbacks, Desktop-UI sowie Arduino-Firmware und einer getrennten seriellen Hardware-Ausgabe. Produktfunktion und Zielkontext bleiben privat.'\n            }\n        ],\n        featured: false\n    },\n    {\n        slug: 'unitfly',\n        name: 'UnitFly',\n        title: 'UnitFly: Commerce Operations mit kontrollierten AI-Agenten',\n        summary: 'Multi-Tenant-Plattform, die Produkt-, Preis-, Bestands- und Marketingabläufe analysiert und AI-gestützte Aktionen nachvollziehbar und begrenzbar macht.',\n        description: 'Sechs getrennte Agentendomänen bearbeiten Preis, Bestand, Content, Bilder, Marketing und Analyse. Deterministische Analyzer wählen die zulässigen Kandidaten aus; das Sprachmodell berät nur innerhalb hart begrenzter Werte.',\n        role: 'Produktidee, Architektur, Frontend, Backend, Datenmodell, AI-Integration, Tests, Containerisierung, eigenständig',\n        year: '2025 bis 2026',\n        status: 'live',\n        discipline: 'product-platforms',\n        liveUrl: 'https://unitfly.de',\n        cover: {\n            src: '/images/work/unitfly.jpg',\n            alt: 'Produktoberfläche und Administrationsbereich der UnitFly-Plattform',\n            position: 'top center'\n        },\n        stack: [\n            'Next.js',\n            'React',\n            'TypeScript',\n            'Python',\n            'FastAPI',\n            'SQLAlchemy',\n            'PostgreSQL',\n            'Docker',\n            'Claude',\n            'OpenAI Embeddings',\n            'Shopware'\n        ],\n        headlineDecision: 'Schreibschutz ist standardmäßig aktiv. Jede schreibende Produktänderung läuft über einen einzigen Write-back-Pfad.',\n        problem: 'Commerce-Teams treffen täglich viele wiederkehrende Entscheidungen über Preise, Bestände, Inhalte, Bilder und Marketing. Ein Sprachmodell kann dabei helfen. Es darf aber nicht unkontrolliert Produktdaten verändern, und ein Ausfall des Modellanbieters darf das System nicht unbenutzbar machen.',\n        approach: 'UnitFly ist als Fullstack-Plattform mit Storefront, Admin-Cockpit, FastAPI-Backend, mandantenweisen Datenbanken und Shopware-Anbindung gebaut. Die sechs Agentendomänen sind bewusst getrennt: Ein Preisagent kennt keine Bildverarbeitung, ein Contentagent keine Bestandslogik. Jede Domäne hat ihre eigenen zulässigen Aktionen, und diese Liste ist Code, nicht Prompt.',\n        decisions: [\n            {\n                title: 'Deterministische Analyzer wählen die Kandidaten, nicht das Modell.',\n                rationale: 'Welche Produkte überhaupt zur Diskussion stehen, entscheidet Code mit nachvollziehbaren Regeln. Das Modell sieht nur eine bereits gefilterte Menge. Damit entscheidet nicht das Modell über die riskanteste Frage: „Was fasst das System an?\"'\n            },\n            {\n                title: 'Semantische Suche mit transparentem Keyword-Fallback.',\n                rationale: 'Embeddings brauchen einen externen Dienst. Fällt er aus, schaltet die Suche auf Stichwortsuche um und sagt das im Interface. Ein stiller Qualitätsabfall wäre schlimmer als ein sichtbarer.'\n            },\n            {\n                title: 'Ein einziger Write-back-Pfad.',\n                rationale: 'Alle schreibenden Änderungen gehen durch dieselbe Funktion. Nur so lassen sich Schreibschutz, Rollenprüfung, Tenant-Kontext und Audit an genau einer Stelle erzwingen statt an sieben.'\n            },\n            {\n                title: 'Rollen-, Tenant- und Rate-Limit-Prüfung gilt auch im Autopilot.',\n                rationale: 'Automatisierte Abläufe umgehen sonst gern die Prüfungen, die für Nutzeranfragen gelten. Hier laufen sie durch dieselben Wächter. Ein Agent hat keine Sonderrechte.'\n            },\n            {\n                title: 'Aktionen und feldbezogene Ergebnisse werden auditiert.',\n                rationale: 'Nachvollziehbarkeit ist bei AI-gestützten Änderungen keine Kür. Ohne Audit lässt sich nach einem Fehler nicht rekonstruieren, was das System warum getan hat.'\n            }\n        ],\n        limitation: 'Der belegte Stand ist ein eigenständig entwickeltes und getestetes Projekt. Ein produktiver Kundenbetrieb wird nicht behauptet.',\n        sections: [\n            {\n                heading: 'Qualität',\n                body: 'Am 22. August 2026 liefen lokal 274 Backend- und 8 Frontend-Tests erfolgreich. Sie decken unter anderem Agentenläufe, Autopilot, Tenant-Kontext, Fallbacks, Schreibschutz, Audit und fehlgeschlagene Write-backs ab.'\n            }\n        ],\n        featured: true\n    },\n    {\n        slug: 'void',\n        name: 'VOiD',\n        title: 'VOiD: Privacy-orientierte Mobile Camera App',\n        summary: 'React-Native-App mit FastAPI-Backend und Computer-Vision-Pipeline, die erkannte Gesichtsbereiche adversariell verändert und die Grenzen dieser Methode offen benennt.',\n        description: 'Kamera- und Galerieabläufe, Stärkeauswahl, Kontoverwaltung und Export im Client; authentifizierte API, Quoten, Rate Limits und die OpenCV-Pipeline serverseitig. Bilddaten werden verarbeitet, aber nicht dauerhaft gespeichert.',\n        role: 'Mobile Client, API, Datenmodell, Subscription-Logik, Verarbeitungspipeline, eigenständig',\n        year: '2026',\n        status: 'in-arbeit',\n        discipline: 'privacy-engineering',\n        stack: [\n            'Expo',\n            'React Native',\n            'TypeScript',\n            'Python',\n            'FastAPI',\n            'PostgreSQL',\n            'OpenCV',\n            'SFace',\n            'Docker'\n        ],\n        headlineDecision: 'Bilddaten werden verarbeitet, aber nicht dauerhaft serverseitig gespeichert.',\n        problem: 'Biometrische Gesichtserkennung und automatisierte Profilbildung werden immer leichter zugänglich. VOiD untersucht, wie gezielte, visuell möglichst unauffällige Bildveränderungen die Wiedererkennung erschweren können. Das ist kein Versprechen von Anonymität oder allgemeinem Schutz vor generativen Deepfakes.',\n        approach: 'Mobile Client, authentifizierte API, Daten- und Subscription-Logik sowie die OpenCV-basierte Verarbeitungspipeline sind als ein zusammenhängendes Produkt umgesetzt. Nach der Gesichtslokalisierung werden SPSA-basierte adversarielle Perturbationen gegen Referenz-Embeddings optimiert. Kamera- und Galerieabläufe, Stärkeauswahl, Export, Quoten, Rate Limits und Eingabevalidierung bilden den Produktpfad darum.',\n        decisions: [\n            {\n                title: 'Keine dauerhafte serverseitige Bildspeicherung.',\n                rationale: 'Eine Privacy-App, die Gesichtsbilder aufbewahrt, widerlegt sich selbst. Die Verarbeitung läuft im Arbeitsspeicher, das Ergebnis geht zurück, danach bleibt nichts.'\n            },\n            {\n                title: 'Quoten und Limits werden serverseitig erzwungen.',\n                rationale: 'Ein mobiler Client ist manipulierbar. Jede Prüfung, die nur dort stattfindet, ist keine Prüfung.'\n            },\n            {\n                title: 'Die Wirksamkeit wird als Signal dargestellt, nicht als Garantie.',\n                rationale: 'Die Verfremdung wirkt gegen das getestete Erkennungsmodell. Ob sie gegen ein fremdes wirkt, weiß niemand. Das Interface sagt das, statt einen Haken anzuzeigen.'\n            },\n            {\n                title: 'Mobile UI, API, ML-Pipeline und Datenbank sind klar getrennt.',\n                rationale: 'Die Pipeline ist der Teil, der sich am häufigsten ändert. Getrennt lässt sie sich austauschen, ohne den Client anzufassen.'\n            }\n        ],\n        limitation: 'VOiD ist ein technisches Privacy-Projekt und befindet sich noch in Arbeit. Die Methode garantiert weder Anonymität noch allgemeinen Deepfake-Schutz; ihre Wirksamkeit kann zwischen Erkennungs- und Generationsmodellen variieren.',\n        featured: true\n    },\n    {\n        slug: 'weblabs',\n        name: 'WebLabs',\n        title: 'WebLabs: die Seite, auf der Sie gerade sind',\n        summary: 'Dieses Portfolio: Next.js App Router, Dark-only-Designsystem, technische Case-Studies, strukturierte SEO-Daten, validierter Kontaktweg und Coolify-Deployment.',\n        description: 'Kein Content-Management-System und keine Datenbank, weil beides für diesen Umfang nur Betriebsaufwand wäre. Typisierte Inhalte erzeugen Case-Studies, Leistungsseiten, Metadaten und Sitemap aus konsistenten Quellen; Tests prüfen Vollständigkeit, Kontraste und Links.',\n        role: 'Konzept, Designsystem, Umsetzung, Tests, Deployment, eigenständig',\n        year: '2026',\n        status: 'diese-seite',\n        discipline: 'product-platforms',\n        stack: [\n            'Next.js',\n            'React',\n            'TypeScript',\n            'SCSS Modules',\n            'Vitest',\n            'JSON-LD',\n            'Docker',\n            'Coolify'\n        ],\n        headlineDecision: 'Keine Datenbank. Inhalte sind typisierte Daten im Repository und damit testbar.',\n        problem: 'Ein Portfolio soll nicht nur Projekte auflisten. Es braucht schnelle, zugängliche Seiten, strukturierte Inhalte, einen verlässlichen Kontaktweg und eine Grundlage, die sich später erweitern lässt. Dafür muss heute noch keine Datenbank betrieben werden.',\n        approach: 'Next.js App Router erzeugt Portfolio, Leistungsseiten und Case-Studies statisch. Farb-, Typografie-, Abstands- und Bewegungsebene werden zentral über CSS-Custom-Properties gesteuert. Das feste dunkle Farbsystem, die monochrome Bildsprache und bewusst reduzierte Radien bilden eine konsistente Oberfläche; Docker und Coolify liefern denselben Build reproduzierbar aus.',\n        decisions: [\n            {\n                title: 'Kontraste werden gerechnet, nicht geschätzt.',\n                rationale: 'Ein Test liest die Token-Datei, konvertiert jede oklch-Farbe nach sRGB und prüft jedes Textpaar gegen 4.5:1 und jeden Bedienelementrand gegen 3:1. Ein zu blasser Grauton fällt damit im Testlauf auf, nicht beim Nutzer.'\n            },\n            {\n                title: 'Ein festes Farbsystem statt paralleler Designvarianten.',\n                rationale: 'Die gesamte visuelle Sprache ist für einen kontrollierten dunklen Grund entworfen. Dadurch bleiben Liniengrafiken, Tiefenstaffelung und die warme monochrome Typografie konsistent, während das Markenorange nur die Identität kennzeichnet.'\n            },\n            {\n                title: 'Das Kontaktformular behauptet keinen Erfolg.',\n                rationale: 'Ohne konfiguriertes SMTP meldet es einen Fehler und bietet den direkten Mailto-Weg an, statt eine grüne Bestätigung für eine Nachricht anzuzeigen, die nie versendet wurde.'\n            },\n            {\n                title: 'Inhalte als typisierte Daten, nicht als JSX pro Seite.',\n                rationale: 'Damit ist eine fehlende Case-Study-Sektion ein Typfehler und ein toter Link ein fehlgeschlagener Test. Solche Fehler werden nicht erst zufällig beim Durchklicken entdeckt.'\n            }\n        ],\n        limitation: 'Diese Seite hat bewusst kein CMS und keine Datenbank. Serverseitig existieren nur Healthcheck und Kontaktversand; Buchungen, Zahlungen und ein Adminbereich sind nicht vorhanden.',\n        featured: true\n    },\n    {\n        slug: 'pa-it-services',\n        name: 'PA-IT-Services',\n        title: 'PA-IT-Services: Website mit geschütztem Admin-Dashboard',\n        summary: 'Next.js-Plattform für Kontakt- und Terminabläufe mit PostgreSQL, Authentifizierung, E-Mail-Flows, Rate Limiting und automatisierten Tests.',\n        description: 'Formularvalidierung mit verständlichen Fehlermeldungen, geschützter Adminbereich, Benachrichtigungsabläufe und grundlegende Missbrauchsgrenzen. Containerisiert ausgeliefert.',\n        role: 'Konzeption und Entwicklung',\n        year: '2025',\n        status: 'live',\n        discipline: 'product-platforms',\n        liveUrl: 'https://www.plp-itservice.de',\n        cover: {\n            src: '/images/work/plp-it-services.jpg',\n            alt: 'Website und Serviceoberfläche von PA-IT-Services',\n            position: 'top center'\n        },\n        stack: [\n            'Next.js',\n            'React',\n            'TypeScript',\n            'PostgreSQL',\n            'Auth',\n            'SMTP',\n            'Vitest',\n            'Docker'\n        ],\n        headlineDecision: 'Rate Limiting und serverseitige Validierung vor jedem schreibenden Formularpfad.',\n        problem: 'Kontakt- und Terminanfragen sind für einen Dienstleister der wichtigste Eingang. Ein Formular, das Anfragen still verliert oder von Bots geflutet wird, kostet direkt Aufträge.',\n        approach: 'Öffentliche Website mit Kontakt- und Terminstrecke, dahinter ein geschützter Adminbereich für die Bearbeitung. Validierung findet serverseitig statt; die clientseitige Prüfung ist nur Komfort. Ein- und ausgehende E-Mails laufen über SMTP mit klaren Fehlerzuständen.',\n        decisions: [\n            {\n                title: 'Serverseitige Validierung als einzige Wahrheit.',\n                rationale: 'Clientseitige Prüfung verbessert die Bedienung, schützt aber nichts. Beide Ebenen teilen sich hier dasselbe Schema, damit die Meldungen nicht auseinanderlaufen.'\n            },\n            {\n                title: 'Rate Limiting statt CAPTCHA.',\n                rationale: 'Ein CAPTCHA belastet jeden echten Nutzer, um wenige Bots abzuhalten, und bringt ein Tracking-Problem mit. Eine Begrenzung pro IP und Zeitfenster reicht für diese Angriffsfläche.'\n            },\n            {\n                title: 'Automatisierte UI- und Logiktests.',\n                rationale: 'Formularpfade sind der Teil, der bei jeder Änderung kaputtgeht und den niemand freiwillig manuell durchklickt.'\n            }\n        ],\n        limitation: 'Auftragsarbeit. Screenshots, Kundenname und Referenznennung stehen nur im Rahmen der erteilten Freigabe.',\n        featured: false\n    },\n    {\n        slug: 'paydos-lounge',\n        name: 'Paydos Lounge',\n        title: 'Paydos Lounge: digitale Marken- und Standortpräsenz',\n        summary: 'Responsive Next.js-Website mit bildgeführtem Storytelling, digitaler Karte, Reservierungswegen, Standortinformationen und containerisiertem Deployment.',\n        description: 'Die Website übersetzt die dunkle, hochwertige Atmosphäre der Lounge in eine eigenständige digitale Präsenz. Inhalte, Bilder, Karte, Öffnungszeiten, Reservierung und Anfahrt bilden einen durchgängigen mobilen und desktopfähigen Informationsweg.',\n        role: 'Konzeption, Art Direction, Designsystem, Frontend und Deployment, eigenständig',\n        year: '2025',\n        status: 'live',\n        discipline: 'product-platforms',\n        liveUrl: 'https://paydoslounge.de',\n        cover: {\n            src: '/images/work/paydos-lounge.jpg',\n            alt: 'Dunkle, bildgeführte Website der Paydos Lounge',\n            position: 'top center'\n        },\n        stack: [\n            'Next.js',\n            'React',\n            'TypeScript',\n            'SCSS Modules',\n            'Docker',\n            'Coolify'\n        ],\n        headlineDecision: 'Die Markenwirkung entsteht aus Typografie, Bildrhythmus und Raum, nicht aus dekorativen Interface-Komponenten.',\n        problem: 'Eine lokale Lounge muss Atmosphäre vermitteln und gleichzeitig praktische Fragen zu Karte, Öffnungszeiten, Reservierung und Anfahrt schnell beantworten. Zu viel Effekt würde die Bedienung schwächen; eine rein funktionale Seite würde den Charakter des Ortes verlieren.',\n        approach: 'Eine responsive Next.js-Anwendung verbindet große redaktionelle Bildflächen mit kurzen, klar gegliederten Inhaltsblöcken. Karte, Galerie, Bewertungen, direkte Reservierungskanäle und Standortinformationen bleiben über die gesamte Seite leicht erreichbar. Docker und Coolify bilden den reproduzierbaren Auslieferungsweg.',\n        decisions: [\n            {\n                title: 'Redaktioneller Bildrhythmus statt klassischem Kartenraster.',\n                rationale: 'Die Räume und Lichtstimmungen sind der stärkste Beleg für die Marke. Wechselnde Bild-Text-Kompositionen führen durch den Ort, ohne die Seite in gleichförmige UI-Boxen zu zerlegen.'\n            },\n            {\n                title: 'Direkte Reservierungswege statt eines künstlichen Buchungssystems.',\n                rationale: 'Reservierungen werden telefonisch oder über Instagram entgegengenommen. Die Website bildet diesen realen Ablauf ehrlich ab, statt ein Formular ohne angebundenen Betriebsprozess vorzutäuschen.'\n            },\n            {\n                title: 'Responsive Bildflächen mit stabilen Seitenverhältnissen.',\n                rationale: 'Große Fotos dürfen beim Laden weder den Inhalt verschieben noch auf kleinen Geräten ihren Fokus verlieren. Definierte Bildrahmen und gerätespezifische Größen halten den visuellen Rhythmus stabil.'\n            },\n            {\n                title: 'Containerisierte Auslieferung über einen kontrollierten Deployment-Pfad.',\n                rationale: 'Docker vereinheitlicht Laufzeit und Build; Coolify übernimmt den reproduzierbaren Rollout, ohne die Anwendung an einen proprietären Frontend-Host zu koppeln.'\n            }\n        ],\n        limitation: 'Die Case-Study belegt Konzeption, Umsetzung und öffentliche Auslieferung der Website. Sie enthält keine Aussagen über Besucherzahlen, Reservierungsquote oder geschäftliche Ergebnisse.',\n        featured: false\n    },\n    {\n        slug: 'ipekten-dienstleistung',\n        name: 'Ipekten Dienstleistung',\n        title: 'Ipekten Dienstleistung: serviceorientierte Unternehmenswebsite',\n        summary: 'Responsive Next.js-Website für einen regionalen Dienstleister mit klarer Leistungsarchitektur, Notdienst-Pfad, Kontaktstrecke, lokaler SEO-Basis und Docker-Deployment.',\n        description: 'Die Website bündelt Rohrreinigung, Gebäudereinigung und weitere Gebäudedienstleistungen in einer schnell erfassbaren Seitenstruktur. Region, Erreichbarkeit, Leistungsumfang und Kontaktmöglichkeiten werden ohne Umwege sichtbar gemacht.',\n        role: 'Konzeption, Informationsarchitektur, Frontend, Kontaktstrecke und Deployment, eigenständig',\n        year: '2025',\n        status: 'live',\n        discipline: 'product-platforms',\n        liveUrl: 'https://ipekten.de',\n        cover: {\n            src: '/images/work/ipekten-dienstleistung.jpg',\n            alt: 'Helle Unternehmenswebsite von Ipekten Dienstleistung mit Leistungsübersicht und Kontaktstrecke',\n            position: 'top center'\n        },\n        stack: [\n            'Next.js',\n            'React',\n            'TypeScript',\n            'SCSS Modules',\n            'SMTP',\n            'Docker'\n        ],\n        headlineDecision: 'Notdienst, Kernleistung und Kontakt bleiben als durchgängiger Handlungspfad auf jeder Bildschirmgröße sichtbar.',\n        problem: 'Bei regionalen Dienstleistungen kommen Besucher häufig mit einem konkreten und teilweise dringenden Anliegen. Eine unklare Navigation, versteckte Telefonnummern oder eine ungegliederte Leistungsmenge verlängern den Weg zur Anfrage und schwächen das Vertrauen.',\n        approach: 'Die Next.js-Website ordnet Inhalte nach Nutzerintention: akute Rohrreinigung zuerst, ergänzende Leistungen danach, Vertrauen und Ablauf als Begründung und eine klare Kontaktstrecke als Abschluss. Semantische Inhalte schaffen die Grundlage für lokale Auffindbarkeit; das Formular übergibt Anfragen per SMTP.',\n        decisions: [\n            {\n                title: 'Dringender Kontaktweg und Hauptleistung stehen vor der Unternehmensgeschichte.',\n                rationale: 'Wer wegen eines akuten Problems kommt, braucht Telefonnummer, Region und Leistung sofort. Unternehmensdetails bleiben wichtig, dürfen diesen primären Weg aber nicht blockieren.'\n            },\n            {\n                title: 'Leistungen werden nach Aufgaben gegliedert statt in einer langen Textseite versteckt.',\n                rationale: 'Klare Abschnittsüberschriften und eigenständige Leistungsblöcke verbessern Scanbarkeit, interne Verlinkung und die semantische Grundlage für regionale Suchanfragen.'\n            },\n            {\n                title: 'Die Kontaktstrecke verbindet direkte Kanäle mit einem strukturierten Formular.',\n                rationale: 'Telefon eignet sich für dringende Fälle, ein Formular für planbare Anfragen. Beide Wege bleiben sichtbar und führen zu einem tatsächlichen Kommunikationskanal statt zu einer rein dekorativen CTA.'\n            },\n            {\n                title: 'Containerisiertes Deployment statt manueller Serverzustände.',\n                rationale: 'Docker hält Anwendung und Laufzeit reproduzierbar. Änderungen lassen sich damit als definierter Build ausliefern, ohne vom zufälligen Zustand des Servers abhängig zu sein.'\n            }\n        ],\n        limitation: 'Die Case-Study dokumentiert die technische Website-Umsetzung und öffentliche Erreichbarkeit. Rankings, Anfragevolumen und geschäftliche Wirkung werden nicht als Ergebnis behauptet.',\n        featured: false\n    }\n];\nconst featuredProjects = projects.filter((p)=>p.featured);\nfunction getProject(slug) {\n    return projects.find((p)=>p.slug === slug);\n}\nconst statusLabel = {\n    live: 'Öffentlich erreichbar',\n    'in-arbeit': 'In Arbeit',\n    lokal: 'Lokal entwickelt',\n    'diese-seite': 'Diese Seite'\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./src/content/projects.ts\n");

